fun setMotorSpeed(speed: Double): Double {
    // Throw IllegalArgumentException if speed is outside -1.0 to 1.0
    // Otherwise return the speed
}

solutionCode:
fun setMotorSpeed(speed: Double): Double {
    if (speed < -1.0 || speed > 1.0) {
        throw IllegalArgumentException("Speed out of range: $speed")
    }
    return speed
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testValidSpeed() {
        Assert.assertEquals(0.5, setMotorSpeed(0.5), 0.001)
    }

    @Test
    fun testZeroSpeed() {
        Assert.assertEquals(0.0, setMotorSpeed(0.0), 0.001)
    }

    @Test
    fun testNegativeValidSpeed() {
        Assert.assertEquals(-1.0, setMotorSpeed(-1.0), 0.001)
    }

    @Test
    fun testMaxValidSpeed() {
        Assert.assertEquals(1.0, setMotorSpeed(1.0), 0.001)
    }

    @Test
    fun testSpeedTooHighMessage() {
        try {
            setMotorSpeed(1.5)
            Assert.fail("Should have thrown IllegalArgumentException")
        } catch (e: IllegalArgumentException) {
            Assert.assertEquals("Speed out of range: 1.5", e.message)
        }
    }

    @Test(expected = IllegalArgumentException::class)
    fun testSpeedTooLow() {
        setMotorSpeed(-2.0)
    }
}
